#define SECTOR_SIZE 512

static void write_segment(Elf64_Phdr phdr, FILE * fp,
                          FILE * img, int *nbytes)
{
    char buf[SECTOR_SIZE];
    long remaining;
    int chunk, padding;

    if (phdr.p_memsz == 0) {
        return;
    }

    /* copy the file contents of the segment into the image */
    fseek(fp, phdr.p_offset, SEEK_SET);
    remaining = phdr.p_filesz;
    while (remaining > 0) {
        chunk = remaining > SECTOR_SIZE ? SECTOR_SIZE : (int)remaining;
        fread(buf, chunk, 1, fp);
        fwrite(buf, chunk, 1, img);
        *nbytes += chunk;
        remaining -= chunk;
    }

    /* zero-fill the rest of the segment (bss) */
    memset(buf, 0, SECTOR_SIZE);
    remaining = phdr.p_memsz - phdr.p_filesz;
    while (remaining > 0) {
        chunk = remaining > SECTOR_SIZE ? SECTOR_SIZE : (int)remaining;
        fwrite(buf, chunk, 1, img);
        *nbytes += chunk;
        remaining -= chunk;
    }

    /* pad the image up to a 512-byte sector boundary */
    padding = SECTOR_SIZE - (*nbytes % SECTOR_SIZE);
    if (padding != SECTOR_SIZE) {
        fwrite(buf, padding, 1, img);
        *nbytes += padding;
    }
}

static void write_os_size(int nbytes, FILE * img)
{
    /* the image starts with one bootblock sector followed by the OS;
       record the OS sector count as a halfword at offset 508 (0x1fc)
       so that the bootblock knows how many sectors to load */
    short os_sectors = (short)(nbytes / SECTOR_SIZE - 1);

    fseek(img, 508, SEEK_SET);
    fwrite(&os_sectors, sizeof(short), 1, img);
    fseek(img, nbytes, SEEK_SET);
}

