// the address of previous pcb in a0
// the address of next pcb in a1
ENTRY(switch_to)
  /* store all callee save registers */
  mv tp, a0
  SAVE_CONTEXT

  /* restore all callee save registers */
  mv tp, a1
  RESTORE_CONTEXT

  jr ra
ENDPROC(switch_to)
