// The beginning of everything
int main()
{
    // init Process Control Block
    init_pcb();
    printk("> [INIT] PCB initialization succeeded.\n\r");

    // init screen
    init_screen();
    printk("> [INIT] SCREEN initialization succeeded.\n\r");

    while (1) {
        // surrender control do_scheduler();
        do_scheduler();
    }

    return 0;
}

