void do_mutex_lock_acquire(mutex_lock_t *lock)
{
    /* try to grab the lock atomically; if it is already held,
       block on the lock's queue and retry when woken up */
    while (atomic_swap_d((uint64_t)LOCKED,
                         (ptr_t)(&(lock->lock.status))) == LOCKED) {
        do_block(&current_running->list, &lock->block_queue);
        do_scheduler();
    }
}

void do_mutex_lock_release(mutex_lock_t *lock)
{
    lock->lock.status = UNLOCKED;

    /* wake up one blocked waiter if any */
    if (!list_empty(&lock->block_queue)) {
        do_unblock(lock->block_queue.next);
    }
}

