int do_kill(pid_t pid)
{
    /* search the pcb with the given pid */
    pcb_t *kill_pcb = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            kill_pcb = &pcb[i];
            break;
        }
    }
    if (kill_pcb == NULL) {
        return 0;
    }

    /* release all the binary semaphores held by the victim */
    while (kill_pcb->binsem_num > 0) {
        int binsem_id = kill_pcb->binsem_id[--kill_pcb->binsem_num];
        binsem_node_t *node = &binsem_nodes[binsem_id];
        if (!list_empty(&node->block_queue)) {
            do_unblock(node->block_queue.next);
        } else {
            node->sem++;
        }
    }

    /* wake up all the processes waiting for the victim */
    while (!list_empty(&kill_pcb->wait_list)) {
        do_unblock(kill_pcb->wait_list.next);
    }

    if (kill_pcb->status == TASK_RUNNING) {
        /* the victim is running on another core: mark it as killed,
           it will be reaped by the scheduler of that core */
        kill_pcb->status = TASK_KILLED;
    } else {
        /* the victim is in some queue: remove it and hand it
           over to the reaper of core 0 */
        list_del(&kill_pcb->list);
        kill_pcb->status = TASK_EXITED;
        list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
    }

    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs)
{
    /* search the pcb with the given pid */
    pcb_t *wait_pcb = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            wait_pcb = &pcb[i];
            break;
        }
    }
    if (wait_pcb == NULL) {
        return 0;
    }

    if (wait_pcb->status == TASK_ZOMBIE) {
        /* the target has exited: hand it over to the reaper */
        wait_pcb->status = TASK_EXITED;
        list_add_tail(&wait_pcb->list, &kernel_pcb[0].wait_list);
        return pid;
    }

    /* the target is still alive: block on its wait list and re-execute
       this system call (via sepc) after being woken up */
    regs->sepc -= 4;
    do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
    scheduler();

    return pid;
}

