int do_mbox_open(char *name)
{
    /* search for an existing mailbox with the same name */
    for (int i = 0; i < MBOX_NUM; i++) {
        if (message_status[i] && kstrcmp(mailbox[i].name, name) == 0) {
            message[i].opned++;
            return i;
        }
    }

    /* allocate a new mailbox */
    int id = free_mailbox++;
    if (id >= MBOX_NUM) {
        return -1;
    }
    kstrcpy(mailbox[id].name, name);
    mailbox[id].id = id;
    message_status[id] = 1;
    message[id].opned = 1;
    message[id].msg_len = 0;
    init_list_head(&message[id].wait_queue);

    return id;
}

